package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8cCreateSheetManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"id\":\"p\",\"name\":\"P\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"a\",\"t\":1}}}}},\"activeSheet\":\"s\"}");}
    private ArrayNode scopes(){return (ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:F6\"}]");}
    private ObjectNode action(){ObjectNode a=obj().put("schemaVersion","2.0").put("type","createSheet").put("newSheetName","Generated").put("rowCount",6).put("columnCount",6);a.set("target",obj().put("sheetId","s"));return a;}
    private void reject(Runnable r){try{r.run();fail("unsafe sheet accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testStableIdAndExactWorkbookTransition(){ObjectNode before=snapshot(),a=action(),m=StructureManifest.preview(before,a,scopes()),again=StructureManifest.preview(before,a,scopes());String id=m.path("structurePatch").path("newSheetId").asText();assertTrue(id.startsWith("ai-"));assertEquals(id,again.path("structurePatch").path("newSheetId").asText());ObjectNode saved=StructureManifest.apply(before,m);assertEquals(2,saved.path("sheetOrder").size());assertEquals(id,saved.path("sheetOrder").get(1).asText());assertEquals("Generated",saved.path("sheets").path(id).path("name").asText());assertEquals("a",saved.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());assertEquals("s",saved.path("activeSheet").asText());StructureManifest.validateReceipt(m,m.path("structureReadback"));ObjectNode change=obj().put("kind","controlled-structure").put("operationId","call").put("afterHash",hash(saved));change.set("structurePatch",m.path("structurePatch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);ObjectNode verify=obj().put("kind","matches_structure").put("sheetId","s").put("range","A1:F6");verify.set("write",write);assertTrue(AgentTools.verify(saved,verify).path("passed").asBoolean());}
    public void testScopeNameBudgetAndTamperReject(){ObjectNode a=action();reject(()->StructureManifest.preview(snapshot(),a,(ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:E6\"}]")));ObjectNode duplicate=a.deepCopy();duplicate.put("newSheetName","Source");reject(()->StructureManifest.preview(snapshot(),duplicate,scopes()));ObjectNode invalidName=a.deepCopy();invalidName.put("newSheetName","Bad\nName");reject(()->StructureManifest.preview(snapshot(),invalidName,scopes()));ObjectNode large=a.deepCopy();large.put("rowCount",100).put("columnCount",100);reject(()->StructureManifest.preview(snapshot(),large,scopes()));ObjectNode overflow=a.deepCopy();overflow.put("rowCount",4294967302L);reject(()->StructureManifest.preview(snapshot(),overflow,scopes()));ObjectNode formula=snapshot();((ObjectNode)formula.path("sheets").path("s").path("cellData").path("0").path("0")).put("f","=1+1");reject(()->StructureManifest.preview(formula,a,scopes()));ObjectNode m=StructureManifest.preview(snapshot(),a,scopes()),forged=m.deepCopy();((ObjectNode)forged.path("structurePatch")).put("newSheetName","Forged");reject(()->StructureManifest.apply(snapshot(),forged));reject(()->StructureManifest.validateReceipt(m,obj().put("sheetId","bad")));}
    public void testIndependentGate(){ArrayNode actions=arr().add(action());reject(()->WriteManifest.classify(actions,false,false,false,false,true));assertEquals("controlled-values",WriteManifest.classify(actions,false,false,false,false,false,true));assertTrue(WriteManifest.availableActions(false,false,false,false,false,true).contains("createSheet"));assertFalse(WriteManifest.availableActions(false,false,false,false,true).contains("createSheet"));}
}
